import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTier } from '../config/TierContext';
import { Tier } from '../config/tiers';

const SIDEBAR_WIDTH = 260;

const analyticsNav = [
  { path: '/', label: 'Travel Overview', aiOnly: false, icon: (
    <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
      <rect x="1" y="1" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="10" y="1" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="1" y="10" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="10" y="10" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
  { path: '/dashboard', label: 'Analytics Dashboard', aiOnly: false, icon: (
    <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
      <rect x="2" y="9" width="3.5" height="7" rx="1" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="7.25" y="5" width="3.5" height="11" rx="1" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="12.5" y="2" width="3.5" height="14" rx="1" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
  { path: '/spotter', label: 'JETT AI', aiOnly: true, icon: (
    <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
      <circle cx="9" cy="9" r="7" stroke="currentColor" strokeWidth="1.5"/>
      <circle cx="9" cy="9" r="3" fill="currentColor"/>
    </svg>
  )},
  { path: '/reports', label: 'Reports', aiOnly: false, icon: (
    <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
      <rect x="3" y="1" width="12" height="16" rx="2" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="5.5" x2="12" y2="5.5" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="9" x2="12" y2="9" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="12.5" x2="10" y2="12.5" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
];

const settingsNav = [
  { path: '/settings', label: 'Settings', icon: (
    <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
      <circle cx="9" cy="9" r="3" stroke="currentColor" strokeWidth="1.5"/>
      <path d="M9 1.5v2M9 14.5v2M1.5 9h2M14.5 9h2M3.4 3.4l1.4 1.4M13.2 13.2l1.4 1.4M3.4 14.6l1.4-1.4M13.2 4.8l1.4-1.4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
    </svg>
  )},
];

const TIERS: Tier[] = ['Starter', 'Essentials', 'Pro'];

export default function Sidebar() {
  const location = useLocation();
  const { tier, setTier, spotterEnabled } = useTier();

  const linkStyle = (path: string): React.CSSProperties => {
    const active = location.pathname === path;
    return {
      display: 'flex',
      alignItems: 'center',
      gap: 10,
      textDecoration: 'none',
      fontSize: 13.5,
      fontWeight: active ? 600 : 400,
      color: active ? '#5B21B6' : '#6B7280',
      padding: '9px 12px',
      borderRadius: 7,
      backgroundColor: active ? '#EDE9FE' : 'transparent',
      transition: 'all 0.15s ease',
      marginBottom: 1,
    };
  };

  const lockedLinkStyle = (path: string): React.CSSProperties => ({
    ...linkStyle(path),
    opacity: 0.5,
    cursor: 'default',
  });

  return (
    <aside
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        bottom: 0,
        width: SIDEBAR_WIDTH,
        backgroundColor: '#ffffff',
        borderRight: '1px solid #E5E7EB',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 100,
      }}
    >
      {/* Logo */}
      <div style={{ padding: '1.5rem 1.25rem 1rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{ color: '#9CA3AF', fontSize: 11, fontWeight: 400 }}>
            Powered by
          </span>
          <span style={{ color: '#111827', fontWeight: 800, fontSize: 18, letterSpacing: '-0.5px' }}>
            JETT
          </span>
        </div>
      </div>

      {/* Subscription Tier */}
      <div style={{ padding: '0 1.25rem 0.75rem' }}>
        <div style={{ color: '#9CA3AF', fontSize: 10, fontWeight: 600, letterSpacing: '1.2px', textTransform: 'uppercase', marginBottom: 8 }}>
          Subscription Tier
        </div>
        <div style={{ display: 'flex', backgroundColor: '#F3F4F6', borderRadius: 7, padding: 3 }}>
          {TIERS.map((t) => (
            <div
              key={t}
              onClick={() => setTier(t)}
              style={{
                flex: 1,
                textAlign: 'center',
                padding: '5px 0',
                fontSize: 11.5,
                fontWeight: t === tier ? 600 : 400,
                color: t === tier ? '#5B21B6' : '#9CA3AF',
                backgroundColor: t === tier ? '#ffffff' : 'transparent',
                borderRadius: 5,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                border: t === tier ? '1px solid #E5E7EB' : '1px solid transparent',
              }}
            >
              {t}
            </div>
          ))}
        </div>
      </div>

      {/* Analytics section label */}
      <div style={{ padding: '0.75rem 1.25rem 0.25rem' }}>
        <div style={{ color: '#D1D5DB', fontSize: 10, fontWeight: 600, letterSpacing: '1.2px', textTransform: 'uppercase' }}>
          Analytics
        </div>
      </div>

      <nav style={{ padding: '0.25rem 0.75rem', display: 'flex', flexDirection: 'column', flex: 1 }}>
        {analyticsNav.map((item) => {
          const locked = item.aiOnly && !spotterEnabled;
          if (locked) {
            return (
              <Link key={item.path} to={item.path} style={lockedLinkStyle(item.path)}>
                <span style={{ display: 'flex', alignItems: 'center', width: 18, justifyContent: 'center' }}>{item.icon}</span>
                <span style={{ flex: 1 }}>{item.label}</span>
                <span style={{
                  fontSize: 9,
                  fontWeight: 700,
                  backgroundColor: '#EDE9FE',
                  color: '#7C3AED',
                  padding: '2px 6px',
                  borderRadius: 4,
                  letterSpacing: '0.5px',
                  textTransform: 'uppercase',
                }}>PRO</span>
              </Link>
            );
          }
          return (
            <Link key={item.path} to={item.path} style={linkStyle(item.path)}>
              <span style={{ display: 'flex', alignItems: 'center', width: 18, justifyContent: 'center' }}>{item.icon}</span>
              {item.label}
            </Link>
          );
        })}

        <div style={{ flex: 1 }} />

        {settingsNav.map((item) => (
          <Link key={item.path} to={item.path} style={linkStyle(item.path)}>
            <span style={{ display: 'flex', alignItems: 'center', width: 18, justifyContent: 'center' }}>{item.icon}</span>
            {item.label}
          </Link>
        ))}
      </nav>

      {/* User profile */}
      <div
        style={{
          padding: '0.875rem 1.25rem',
          borderTop: '1px solid #F3F4F6',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
        }}
      >
        <div
          style={{
            width: 34,
            height: 34,
            backgroundColor: '#7C3AED',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
          }}
        >
          <span style={{ color: '#fff', fontWeight: 700, fontSize: 12 }}>JT</span>
        </div>
        <div style={{ lineHeight: 1.3 }}>
          <div style={{ color: '#111827', fontWeight: 600, fontSize: 13 }}>JETT Analytics</div>
          <div style={{ color: '#9CA3AF', fontSize: 11 }}>{tier} Tier</div>
        </div>
      </div>
    </aside>
  );
}

